<script setup lang="ts">
import {computed,ref} from 'vue';
import type {CatalogEntry,ReadingExam} from './model';
import {validateExam} from './adapter';
import {customExams,saveCustomExams,downloadJson,readingStorageWarning} from './storage';
import {loadExam} from './repository';
const props=defineProps<{catalog:CatalogEntry[]}>();const emit=defineEmits<{start:[string]}>();
const search=ref('');const part=ref('all');const origin=ref('all');const page=ref(1);const message=ref('');const editor=ref('');const editingId=ref('');const showEditor=ref(false);const importing=ref(false);
const entries=computed(()=>[...customExams.value.map(e=>({...e,custom:true})),...props.catalog]);
const filtered=computed(()=>entries.value.filter(e=>(part.value==='all'||e.part===part.value)&&(origin.value==='all'||(origin.value==='custom'?e.custom:!e.custom))&&`${e.title} ${e.source.label}`.toLowerCase().includes(search.value.trim().toLowerCase())));
const visible=computed(()=>filtered.value.slice((page.value-1)*12,page.value*12));const pages=computed(()=>Math.max(1,Math.ceil(filtered.value.length/12)));
function reset(){page.value=1;}
function example():ReadingExam{return {version:1,id:`custom-${crypto.randomUUID()}`,title:'自建阅读示例：A small library',part:'P1',frequency:'自建',questionCount:2,source:{label:'自编示例文章与试题',reference:'请替换为你的文章与题目来源'},passageHtml:'<h2>A small library</h2><p>A small library opened in 2024. Local volunteers donated books to help children read.</p>',groups:[{id:'g1',kind:'short_answer',title:'阅读理解',instructionsHtml:'<p>根据文章回答以下问题。</p>',questions:[{id:'q1',label:'1',kind:'text',promptHtml:'<p>In which year did the library open?</p>',options:[],accepted:['2024'],points:1,maxWords:1},{id:'q2',label:'2',kind:'choice',promptHtml:'<p>Who donated the books?</p>',options:[{value:'A',label:'A. Local volunteers'},{value:'B',label:'B. Teachers'}],accepted:['A'],points:1}]}]};}
function create(){editingId.value='';editor.value=JSON.stringify(example(),null,2);message.value='';showEditor.value=true;}
async function edit(entry:CatalogEntry){try{const exam=await loadExam(entry.id);editingId.value=entry.custom?entry.id:'';editor.value=JSON.stringify(entry.custom?exam:{...exam,id:`custom-${crypto.randomUUID()}`,title:`${exam.title}（副本）`,custom:true},null,2);showEditor.value=true;message.value='';}catch(error){message.value=(error as Error).message;}}
function saveEditor(){try{const exam=validateExam(JSON.parse(editor.value));if(props.catalog.some(e=>e.id===exam.id))throw new Error('自建题目的编号不能与内置题库相同。');if(exam.id!==editingId.value&&customExams.value.some(e=>e.id===exam.id))throw new Error('此编号已存在，请使用新的编号。');const next=[{...exam,custom:true},...customExams.value.filter(e=>e.id!==editingId.value)];if(saveCustomExams(next)){showEditor.value=false;message.value='题目已保存。';page.value=1;}}catch(error){message.value=(error as Error).message;}}
async function importFile(event:Event){const input=event.target as HTMLInputElement;const file=input.files?.[0];if(!file)return;importing.value=true;message.value='';try{if(file.size>5*1024*1024)throw new Error('单个导入文件不能超过 5 MB。');const data=JSON.parse(await file.text());const list=Array.isArray(data)?data:[data];if(!list.length||list.length>100)throw new Error('每次可导入 1–100 篇文章。');const exams=list.map(validateExam);if(new Set(exams.map(e=>e.id)).size!==exams.length||exams.some(e=>entries.value.some(old=>old.id===e.id)))throw new Error('导入编号重复或已存在，请修改编号后重试。');if(saveCustomExams([...exams.map(e=>({...e,custom:true})),...customExams.value])){message.value=`已导入 ${exams.length} 篇文章。`;page.value=1;}}catch(error){message.value=(error as Error).message;}finally{importing.value=false;input.value='';}}
function remove(entry:CatalogEntry){if(!window.confirm(`删除自建题目“${entry.title}”？已完成的练习记录会保留。`))return;if(saveCustomExams(customExams.value.filter(e=>e.id!==entry.id)))message.value='自建题目已删除。';page.value=Math.min(page.value,pages.value);}
async function exportOne(entry:CatalogEntry){try{downloadJson(`${entry.id}.json`,await loadExam(entry.id));}catch(error){message.value=(error as Error).message;}}
</script>
<template><section><header class="rp-section-header"><div><span class="rp-eyebrow">YOUR READING SPACE</span><h1>让每一次阅读，<br>都有所积累。</h1><p class="rp-muted">选择一篇文章开始练习，遇见的生词留给下一次复习。</p></div><div class="rp-library-summary"><strong>{{entries.length}}</strong><span>篇阅读文章</span><small>{{customExams.length}} 篇自建</small></div></header><div class="rp-panel"><div class="rp-row rp-wrap"><div><h2>阅读题库</h2><p class="rp-caption">内置题目可复制编辑，自建题目支持导入、导出和删除。</p></div><div class="rp-row rp-wrap"><button class="rp-button secondary" @click="downloadJson('reading-example.json',example())">格式示例</button><label class="rp-button secondary rp-file-label">{{importing?'正在导入…':'导入 JSON'}}<input type="file" accept="application/json,.json" :disabled="importing" @change="importFile"></label><button class="rp-button" @click="create">＋ 新建题目</button></div></div><div class="rp-filters"><label class="rp-field"><span class="rp-caption">搜索文章</span><input v-model="search" type="search" placeholder="文章名称或来源" @input="reset"></label><label class="rp-field"><span class="rp-caption">文章部分</span><select v-model="part" @change="reset"><option value="all">全部 Part</option><option v-for="p in ['P1','P2','P3']" :key="p">{{p}}</option></select></label><label class="rp-field"><span class="rp-caption">题库来源</span><select v-model="origin" @change="reset"><option value="all">全部题库</option><option value="builtin">内置题库</option><option value="custom">自建题库</option></select></label></div><p v-if="message" class="rp-notice" role="status">{{message}}</p><div class="rp-catalog-grid"><article v-for="entry in visible" :key="entry.id" class="rp-exam-card"><div class="rp-row"><span class="rp-tag">{{entry.part}}</span><span class="rp-caption">{{entry.questionCount}} 题 · {{entry.custom?'自建':'内置'}}</span></div><h3>{{entry.title}}</h3><p class="rp-caption">{{entry.source.label}}</p><button class="rp-button" @click="emit('start',entry.id)">开始阅读 →</button><div class="rp-card-tools"><button class="rp-link" @click="edit(entry)">{{entry.custom?'编辑':'复制编辑'}}</button><button class="rp-link" @click="exportOne(entry)">导出</button><button v-if="entry.custom" class="rp-link danger" @click="remove(entry)">删除</button></div></article></div><p v-if="!visible.length" class="rp-empty">没有匹配的文章，试试其他关键词或导入自建题目。</p><nav class="rp-pagination" aria-label="题库分页"><button class="rp-button secondary" :disabled="page<=1" @click="page--">上一页</button><span class="rp-caption">{{filtered.length}} 篇 · {{page}} / {{pages}}</span><button class="rp-button secondary" :disabled="page>=pages" @click="page++">下一页</button></nav></div><div v-if="showEditor" class="rp-modal-backdrop"><section class="rp-dialog wide" role="dialog" aria-modal="true" aria-labelledby="editor-title"><div class="rp-row"><h2 id="editor-title">{{editingId?'编辑题目':'新建题目'}}</h2><button class="rp-icon-button" aria-label="关闭题目编辑" @click="showEditor=false">×</button></div><p class="rp-caption">使用 ReadingExam v1 JSON 格式。文章与题目来源必填；粘贴的 HTML 会过滤脚本和事件属性。</p><label class="rp-field">题目 JSON<textarea v-model="editor" rows="18" spellcheck="false"></textarea></label><p v-if="message" role="alert" class="rp-error">{{message}}</p><p v-if="readingStorageWarning" role="alert" class="rp-error">{{readingStorageWarning}}</p><div class="rp-row rp-actions"><button class="rp-button secondary" @click="showEditor=false">取消</button><button class="rp-button" @click="saveEditor">保存题目</button></div></section></div></section></template>
